from typing import Any
import csv
import io

REQUIRED_COLUMNS = ('name', 'email', 'role')
VALID_ROLES = ('admin', 'editor', 'viewer')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


def read_rows(filename: str, content: bytes) -> tuple[list[str], list[tuple[int, dict[str, Any]]]]:
    name = filename.lower()
    if name.endswith('.xlsx'):
        from openpyxl import load_workbook
        book = load_workbook(io.BytesIO(content), read_only=True, data_only=True)
        lines = book.active.iter_rows(values_only=True)
        first = next(lines, None) or ()
        header = [str(h or '').strip().lstrip('\ufeff').lower() for h in first]
        rows = []
        for number, values in enumerate(lines, 2):
            if all(v is None or str(v).strip() == '' for v in values):
                continue
            rows.append((number, dict(zip(header, values))))
            if len(rows) > MAX_ROWS:
                break
        book.close()
        return (header, rows)
    if not name.endswith('.csv'):
        raise ValueError('unsupported file type; upload a .csv or .xlsx file')
    reader = csv.DictReader(io.StringIO(content.decode('utf-8-sig')))
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    reader.fieldnames = header
    rows = []
    for row in reader:
        rows.append((reader.line_num, row))
        if len(rows) > MAX_ROWS:
            break
    return (header, rows)


def validate_users_upload(filename: str, content: bytes, max_rows: int = MAX_ROWS) -> list[dict[str, Any]]:
    """Return a list of {"row": spreadsheet row/line number, "errors": [reasons]} for bad rows only."""
    header, rows = read_rows(filename, content)
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}]
    bad, seen = ([], set())
    for count, (number, row) in enumerate(rows, 1):
        if count > max_rows:
            bad.append({'row': number, 'errors': [f'more than {max_rows} rows; stopped']})
            break
        name = str(row.get('name') or '').strip()
        email = str(row.get('email') or '').strip().lower()
        role = str(row.get('role') or '').strip().lower()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if not email:
            problems.append('email is required')
        elif len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if not role:
            problems.append('role is required')
        elif role not in VALID_ROLES:
            problems.append(f"role must be one of: {', '.join(VALID_ROLES)}")
        if problems:
            bad.append({'row': number, 'errors': problems})
        elif email:
            seen.add(email)
    return bad

